#include "numerix.h"
#include <math.h>
#include <stdlib.h>
#include <string.h>
static numerix_status fail(numerix_error*e,numerix_status s,const char*m){return numerix_error_set(e,s,m);}
void numerix_ode_solution_destroy(numerix_ode_solution*s){if(s){free(s->x);free(s->y);memset(s,0,sizeof(*s));}}
static numerix_status call(numerix_ode_function f,void*d,double x,const double*y,size_t n,double*out,numerix_ode_solution*s,numerix_error*e){size_t i;numerix_status st=f(x,y,n,out,d);s->function_evaluations++;if(st!=NUMERIX_STATUS_SUCCESS)return fail(e,st,"ODE callback failed");for(i=0;i<n;i++)if(!isfinite(out[i]))return fail(e,NUMERIX_STATUS_NUMERICAL_FAILURE,"ODE callback returned non-finite derivative");return NUMERIX_STATUS_SUCCESS;}
static numerix_status solve(numerix_ode_function f,void*d,double x0,const double*y0,size_t n,double h,size_t steps,numerix_ode_solution*out,numerix_error*e,int method){size_t i,j,points,total;double *k1=NULL,*k2=NULL,*k3=NULL,*k4=NULL,*tmp=NULL; numerix_status s=NUMERIX_STATUS_SUCCESS;if(!out)return fail(e,NUMERIX_STATUS_INVALID_ARGUMENT,"solution output required");memset(out,0,sizeof(*out));if(!f||!y0||!n||!steps||!isfinite(x0)||!isfinite(h)||h==0||steps==SIZE_MAX||n>SIZE_MAX/sizeof(double)||(steps+1)>SIZE_MAX/sizeof(double)||n>SIZE_MAX/(steps+1)||(total=n*(steps+1))>SIZE_MAX/sizeof(double))return fail(e,NUMERIX_STATUS_INVALID_ARGUMENT,"finite initial state, nonzero step, dimension, and step count required");points=steps+1;for(j=0;j<n;j++)if(!isfinite(y0[j]))return fail(e,NUMERIX_STATUS_INVALID_INPUT,"initial state must be finite");out->x=malloc(points*sizeof(double));out->y=malloc(total*sizeof(double));k1=malloc(n*sizeof(double));if(method>=1)k2=malloc(n*sizeof(double));if(method>=2){k3=malloc(n*sizeof(double));k4=malloc(n*sizeof(double));}tmp=malloc(n*sizeof(double));if(!out->x||!out->y||!k1||(method>=1&&!k2)||(method>=2&&(!k3||!k4))||!tmp){s=NUMERIX_STATUS_ALLOCATION_FAILURE;goto cleanup;}out->points=points;out->dimension=n;out->status=NUMERIX_STATUS_SUCCESS;memcpy(out->y,y0,n*sizeof(double));out->x[0]=x0;for(i=0;i<steps;i++){double x=out->x[i],xn=x+h;const double*y=out->y+i*n;double*yn=out->y+(i+1)*n;if(!isfinite(xn)){s=NUMERIX_STATUS_NUMERICAL_FAILURE;goto cleanup;}s=call(f,d,x,y,n,k1,out,e);if(s)goto cleanup;if(method==0){for(j=0;j<n;j++)yn[j]=y[j]+h*k1[j];}else if(method==1){for(j=0;j<n;j++)tmp[j]=y[j]+h*k1[j];s=call(f,d,xn,tmp,n,k2,out,e);if(s)goto cleanup;for(j=0;j<n;j++)yn[j]=y[j]+h*(k1[j]+k2[j])*0.5;}else{for(j=0;j<n;j++)tmp[j]=y[j]+0.5*h*k1[j];s=call(f,d,x+0.5*h,tmp,n,k2,out,e);if(s)goto cleanup;for(j=0;j<n;j++)tmp[j]=y[j]+0.5*h*k2[j];s=call(f,d,x+0.5*h,tmp,n,k3,out,e);if(s)goto cleanup;for(j=0;j<n;j++)tmp[j]=y[j]+h*k3[j];s=call(f,d,xn,tmp,n,k4,out,e);if(s)goto cleanup;for(j=0;j<n;j++)yn[j]=y[j]+h*(k1[j]+2*k2[j]+2*k3[j]+k4[j])/6.0;}for(j=0;j<n;j++)if(!isfinite(yn[j])){s=NUMERIX_STATUS_NUMERICAL_FAILURE;goto cleanup;}out->x[i+1]=xn;}out->status=NUMERIX_STATUS_SUCCESS;numerix_error_clear(e);free(k1);free(k2);free(k3);free(k4);free(tmp);return s;
cleanup:out->status=s;free(k1);free(k2);free(k3);free(k4);free(tmp);numerix_ode_solution_destroy(out);out->status=s;if(e&&e->code==NUMERIX_STATUS_SUCCESS)numerix_error_set(e,s,numerix_status_string(s));return s;}
numerix_status numerix_ode_euler(numerix_ode_function f,void*d,double x,const double*y,size_t n,double h,size_t steps,numerix_ode_solution*out,numerix_error*e){return solve(f,d,x,y,n,h,steps,out,e,0);}
numerix_status numerix_ode_heun(numerix_ode_function f,void*d,double x,const double*y,size_t n,double h,size_t steps,numerix_ode_solution*out,numerix_error*e){return solve(f,d,x,y,n,h,steps,out,e,1);}
numerix_status numerix_ode_rk4(numerix_ode_function f,void*d,double x,const double*y,size_t n,double h,size_t steps,numerix_ode_solution*out,numerix_error*e){return solve(f,d,x,y,n,h,steps,out,e,2);}
